import java.io.*;
import java.util.*;

public class CF1187G extends PrintWriter {
    public CF1187G() { super(System.out); }

    static class Reader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        Reader(InputStream in) { reader = new BufferedReader(new InputStreamReader(in)); }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(next()); }
    }

    Reader scan;

    public static void main(String[] args) {
        new CF1187G().start();
    }

    static final int INF = 0x3f3f3f3f;
    List<Integer>[] adj;
    int V, E;
    int[] dist, prevDist, prevEdge;
    int[] from, to, xorVal, cost;
    int[] capacity;

    void init(int n, int m) {
        adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        dist = new int[n];
        prevDist = new int[n];
        prevEdge = new int[n];
        from = new int[m];
        to = new int[m];
        xorVal = new int[m];
        cost = new int[m];
        capacity = new int[m * 2];
        E = 0;
    }

    void addEdge(int u, int v, int cap, int c) {
        int idx = E++;
        from[idx] = u;
        to[idx] = v;
        xorVal[idx] = u ^ v;
        cost[idx] = c;
        capacity[idx * 2] = cap;
        adj[u].add(idx * 2);
        adj[v].add(idx * 2 + 1);
    }

    int[] queue;
    int qf, ql, qmax;
    boolean[] inq;

    void push(int x) {
        if (inq[x]) return;
        if (qf + ql == queue.length) {
            if (ql * 2 <= queue.length) {
                System.arraycopy(queue, qf, queue, 0, ql);
                qf = 0;
            } else {
                int[] tmp = new int[queue.length * 2];
                System.arraycopy(queue, qf, tmp, 0, ql);
                queue = tmp;
                qf = 0;
            }
        }
        queue[qf + ql++] = x;
        inq[x] = true;
    }

    int pop() {
        int x = queue[qf++];
        ql--;
        inq[x] = false;
        return x;
    }

    boolean spfa(int s, int t) {
        Arrays.fill(dist, INF);
        dist[s] = 0;
        qf = ql = 0;
        push(s);

        while (ql > 0) {
            int u = pop();
            int nd = prevDist[u] + 1;

            for (int e : adj[u]) {
                if (capacity[e] > 0) {
                    int idx = e >> 1;
                    int c = (e & 1) == 0 ? cost[idx] : -cost[idx];
                    int ndist = dist[u] + c;
                    int v = u ^ xorVal[idx];

                    if (dist[v] > ndist || (dist[v] == ndist && prevDist[v] > nd)) {
                        dist[v] = ndist;
                        prevDist[v] = nd;
                        prevEdge[v] = e;
                        push(v);
                    }
                }
            }
        }
        return dist[t] != INF;
    }

    void augment(int s, int t) {
        int minCap = INF;
        for (int cur = t; cur != s; cur ^= xorVal[prevEdge[cur] >> 1]) {
            minCap = Math.min(minCap, capacity[prevEdge[cur]]);
        }
        for (int cur = t; cur != s; cur ^= xorVal[prevEdge[cur] >> 1]) {
            int e = prevEdge[cur];
            capacity[e] -= minCap;
            capacity[e ^ 1] += minCap;
        }
    }

    void augmentUnit(int s, int t) {
        for (int cur = t; cur != s; cur ^= xorVal[prevEdge[cur] >> 1]) {
            int e = prevEdge[cur];
            capacity[e]--;
            capacity[e ^ 1]++;
        }
    }

    int minCostFlow(int s, int t) {
        while (spfa(s, t)) {
            augmentUnit(s, t);
        }
        int total = 0;
        for (int i = 0; i < E; i++) {
            total += cost[i] * capacity[i * 2 + 1];
        }
        return total;
    }

    void start() {
        try {
            scan = new Reader(System.in);
            int n = scan.nextInt();
            int m = scan.nextInt();
            int k = scan.nextInt();
            int c = scan.nextInt();
            int d = scan.nextInt();

            int[] special = new int[k];
            for (int i = 0; i < k; i++) special[i] = scan.nextInt() - 1;

            List<Integer>[] g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int u = scan.nextInt() - 1;
                int v = scan.nextInt() - 1;
                g[u].add(v);
                g[v].add(u);
            }

            int T = k + 1;
            int totalNodes = n * T + 1;
            int totalEdges = k + (m * 2 * k + n) * (T - 1);
            init(totalNodes, totalEdges);

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    for (int neighbor : g[i]) {
                        int v = neighbor * T + t + 1;
                        for (int x = 1; x <= k; x++) {
                            addEdge(u, v, 1, c + (x * 2 - 1) * d);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    int v = u + 1;
                    addEdge(u, v, k, i == 0 ? 0 : c);
                }
            }

            for (int i = 0; i < k; i++) {
                addEdge(totalNodes - 1, special[i] * T, 1, 0);
            }

            println(minCostFlow(totalNodes - 1, 0 * T + T - 1));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
